content.content:
1	/* ═══════════════════════════════════════════════════════════════════
2	   NUDIMMUD COMMAND CENTER — ALBEDO DESIGN SYSTEM
3	   One clean file. No patches. No overrides.
4	   ═══════════════════════════════════════════════════════════════════ */
5	
6	/* ─── TOKENS ──────────────────────────────────────────────────────── */
7	:root {
8	    /* ─── 2026 ELITE TOKENS (WARM OPERATOR SHELL) ─── */
9	    --bg-void:        hsl(0, 0%, 0%);
10	    --bg-surface:     hsla(0, 0%, 8%, 0.92);
11	    --bg-glass:       hsla(0, 0%, 8%, 0.72);
12	    
13	    --cyan-glow:      hsl(96, 68%, 74%);
14	    --cyan-dim:       hsl(96, 42%, 24%);
15	    --gold-solar:     hsl(90, 100%, 36%);
16	    --red-fusion:     hsl(12, 84%, 58%);   /* Critical alert */
17	
18	    --silver-albedo:  hsl(0, 0%, 97%);
19	    --text-dim:       hsl(0, 0%, 66%);
20	
21	    /* ─── iC2M TEAM COLORS ─── */
22	    --color-claudio:  hsl(180, 100%, 50%); /* Cyan */
23	    --color-fanny:    hsl(280, 100%, 60%); /* Purple */
24	    --color-cati:     hsl(350, 100%, 55%); /* Red */
25	    --color-marcel:   hsl(120, 100%, 50%); /* Green */
26	    
27	    --font-display:   'Bricolage Grotesque', 'DM Sans', system-ui, sans-serif;
28	    --font-body:      'DM Sans', system-ui, sans-serif;
29	    --font-mono:      'JetBrains Mono', monospace;
30	    
31	    --ease-in-out:    cubic-bezier(0.4, 0, 0.2, 1);
32	    --ease-out:       cubic-bezier(0, 0, 0.2, 1);
33	    --ease-neural:    cubic-bezier(0.23, 1, 0.32, 1);
34	    --ease:           var(--ease-neural);
35	    --transition-master: 250ms var(--ease-neural);
36	
37	    --sidebar-w:      220px;
38	    --panel-w:        320px;
39	    --header-h:       74px;
40	    --footer-h:       52px;
41	    
42	    --grid-unit:      8px;
43	}
44	
45	/* ─── RESET ───────────────────────────────────────────────────────── */
46	*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
47	
48	html, body {
49	    width: 100vw;
50	    height: 100vh;
51	    overflow: hidden;
52	    background: var(--bg-void);
53	    color: var(--silver-albedo);
54	    font-family: var(--font-display);
55	    font-size: 14px;
56	    -webkit-font-smoothing: antialiased;
57	}
58	
59	html {
60	    scroll-behavior: smooth;
61	}
62	
63	body {
64	    -webkit-tap-highlight-color: transparent;
65	    touch-action: manipulation;
66	}
67	
68	button,
69	input,
70	textarea,
71	select {
72	    font: inherit;
73	}
74	
75	h1, h2, h3, h4, h5, h6 {
76	    text-wrap: balance;
77	}
78	
79	.skip-link {
80	    position: fixed;
81	    top: 12px;
82	    left: 12px;
83	    z-index: 20000;
84	    padding: 10px 14px;
85	    border-radius: 999px;
86	    background: rgba(15, 10, 8, 0.98);
87	    border: 1px solid rgba(118, 185, 0, 0.25);
88	    color: var(--gold-solar);
89	    font-family: var(--font-mono);
90	    font-size: 0.62rem;
91	    letter-spacing: 0.14em;
92	    text-decoration: none;
93	    transform: translateY(-180%);
94	    transition: transform 180ms var(--ease-neural), box-shadow 180ms var(--ease-neural);
95	}
96	
97	.skip-link:focus-visible {
98	    transform: translateY(0);
99	    box-shadow: 0 12px 30px rgba(0,0,0,0.35);
100	}
101	
102	/* ─── BACKGROUND LAYERS ───────────────────────────────────────────── */
103	#qi-flow-canvas {
104	    position: fixed;
105	    inset: 0;
106	    width: 100%;
107	    height: 100%;
108	    z-index: 0;
109	    pointer-events: auto; /* receives drag/zoom events */
110	    transition: opacity 0.5s var(--ease-neural);
111	}
112	
113	
114	
115	/* Digital Noise / Hologram Grain */
116	.bridge-active::after {
117	    content: "";
118	    position: fixed;
119	    inset: 0;
120	    z-index: 9999;
121	    pointer-events: none;
122	    background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.65' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E");
123	    opacity: 0.05;
124	}
125	
126	.vignette {
127	    position: fixed;
128	    inset: 0;
129	    z-index: 1;
130	    pointer-events: none;
131	    background: radial-gradient(ellipse at center,
132	        transparent 40%,
133	        rgba(2, 2, 4, 0.7) 100%);
134	}
135	
136	.global-scanline {
137	    position: fixed;
138	    left: 0;
139	    width: 100%;
140	    height: 1px;
141	    z-index: 2;
142	    pointer-events: none;
143	    background: linear-gradient(to right, transparent, rgba(0, 242, 255, 0.12), transparent);
144	    animation: scan 12s linear infinite;
145	}
146	@keyframes scan { from { top: -1px; } to { top: 100vh; } }
147	
148	/* ─── APP SHELL — THE GRID ────────────────────────────────────────── */
149	/*
150	    The shell sits above the canvas (z-index 10).
151	    All interactive children must have pointer-events:auto.
152	    The shell itself is pointer-events:none so gaps fall through to canvas.
153	
154	    Grid layout:
155	      col1=sidebar  col2=content  col3=right-panel
156	      row1=header   row2=main     row3=footer
157	*/
158	.app-shell {
159	    position: fixed;
160	    inset: 0;
161	    z-index: 10;
162	    display: grid;
163	    grid-template-columns: var(--sidebar-w) 1fr;
164	    grid-template-rows: auto 1fr var(--footer-h);
165	    pointer-events: none; /* shell is transparent — UI children opt back in */
166	    transition: grid-template-columns 0.4s cubic-bezier(0.19, 1, 0.22, 1);
167	}
168	
169	.panel-open .app-shell {
170	    grid-template-columns: var(--sidebar-w) 1fr var(--panel-w);
171	}
172	
173	/* ─── HEADER ──────────────────────────────────────────────────────── */
174	header {
175	    grid-column: 1 / -1; /* spans all 3 cols */
176	    grid-row: 1;
177	    display: flex;
178	    align-items: flex-start;
179	    gap: 24px;
180	    padding: 14px 28px 12px;
181	    background: rgba(4, 6, 14, 0.92);
182	    border-bottom: 1px solid rgba(255, 255, 255, 0.06);
183	    backdrop-filter: blur(20px);
184	    pointer-events: auto;
185	    z-index: 20;
186	}
187	
188	.logo {
189	    display: flex;
190	    align-items: center;
191	    flex-shrink: 0;
192	}
193	
194	.shell-route-column {
195	    flex: 1;
196	    min-width: 0;
197	    display: flex;
198	    flex-direction: column;
199	    gap: 12px;
200	}
201	
202	.status-orb {
203	    width: 8px; height: 8px;
204	    border-radius: 50%;
205	    background: var(--cyan-glow);
206	    box-shadow: 0 0 10px var(--cyan-glow);
207	    animation: orb-pulse 2s ease-in-out infinite;
208	}
209	@keyframes orb-pulse {
210	    0%, 100% { opacity: 1; box-shadow: 0 0 8px var(--cyan-glow); }
211	    50%       { opacity: 0.6; box-shadow: 0 0 18px var(--cyan-glow); }
212	}
213	
214	.cortex-command-shell {
215	    flex: 1;
216	    display: flex;
217	    width: 100%;
218	    align-items: center;
219	    gap: 10px;
220	    background: rgba(0, 0, 0, 0.3);
221	    border: 1px solid rgba(255, 255, 255, 0.08);
222	    padding: 10px 14px;
223	    min-height: 36px;
224	    height: auto;
225	    max-width: none;
226	}
227	
228	.shell-route-column {
229	    display: flex;
230	    flex-direction: column;
231	    gap: 8px;
232	    flex: 1;
233	    min-width: 0;
234	}
235	
236	.command-prefix {
237	    font-family: var(--font-mono);
238	    font-size: 0.7rem;
239	    color: var(--cyan-glow);
240	    opacity: 0.6;
241	    flex-shrink: 0;
242	}
243	
244	#global-command-input {
245	    flex: 1;
246	    background: transparent;
247	    border: none;
248	    outline: none;
249	    color: var(--silver-albedo);
250	    font-family: var(--font-mono);
251	    font-size: 0.78rem;
252	    letter-spacing: 0.05em;
253	}
254	#global-command-input::placeholder { opacity: 0.3; }
255	
256	.system-status {
257	    display: flex;
258	    align-items: center;
259	    gap: 16px;
260	    margin-left: auto;
261	    flex-shrink: 0;
262	}
263	
264	.route-directive {
265	    font-family: var(--font-mono);
266	    font-size: 0.55rem;
267	    letter-spacing: 0.22em;
268	    text-transform: uppercase;
269	    color: rgba(255, 255, 255, 0.42);
270	}
271	
272	/* ─── SIDEBAR NAV ─────────────────────────────────────────────────── */
273	nav#sidebar-nav {
274	    grid-column: 1;
275	    grid-row: 2;
276	    display: flex;
277	    flex-wrap: wrap;
278	    gap: 8px;
279	    background: transparent;
280	    border: none;
281	    overflow: visible;
282	    pointer-events: auto;
283	    padding: 0;
284	}
285	
286	.nav-node {
287	    height: auto;
288	    min-height: 38px;
289	    padding: 0 16px;
290	    display: flex;
291	    align-items: center;
292	    cursor: pointer;
293	    border-left: none;
294	    border-bottom: 2px solid transparent;
295	    border-radius: 999px;
296	    background: rgba(255, 255, 255, 0.03);
297	    opacity: 0.45;
298	    transition: var(--ease);
299	    font-family: var(--font-mono);
300	    font-size: 0.68rem;
301	    letter-spacing: 0.14em;
302	}
303	.nav-node:hover {
304	    opacity: 0.8;
305	    background: rgba(255, 255, 255, 0.03);
306	}
307	.nav-node.active {
308	    opacity: 1;
309	    border-bottom-color: var(--cyan-glow);
310	    background: rgba(0, 243, 255, 0.08);
311	    color: var(--cyan-glow);
312	}
313	
314	/* ─── MAIN CONTENT STAGE ──────────────────────────────────────────── */
315	#module-content {
316	    grid-column: 2;
317	    grid-row: 2;
318	    overflow-y: auto;
319	    overflow-x: hidden;
320	    padding: 32px 36px;
321	    pointer-events: auto;
322	    /* Scroll-bar styling */
323	    scrollbar-width: thin;
324	    scrollbar-color: rgba(0, 242, 255, 0.15) transparent;
325	}
326	
327	/* ─── RIGHT TELEMETRY PANEL ───────────────────────────────────────── */
328	aside#system-side-panel {
329	    grid-column: 3;
330	    grid-row: 2;
331	    background: rgba(4, 6, 14, 0.75);
332	    border-left: 1px solid rgba(255, 255, 255, 0.05);
333	    padding: 24px 20px;
334	    display: flex;
335	    flex-direction: column;
336	    gap: 18px;
337	    overflow-y: auto;
338	    pointer-events: auto;
339	}
340	
341	/* ─── FOOTER ──────────────────────────────────────────────────────── */
342	footer {
343	    grid-column: 1 / -1; /* spans all 3 cols */
344	    grid-row: 3;
345	    display: flex;
346	    align-items: center;
347	    padding: 0 28px;
348	    background: rgba(4, 6, 14, 0.92);
349	    border-top: 1px solid rgba(255, 255, 255, 0.05);
350	    font-family: var(--font-mono);
351	    font-size: 0.62rem;
352	    opacity: 0.7;
353	    gap: 28px;
354	    pointer-events: auto;
355	}
356	
357	/* ─── PANELS ──────────────────────────────────────────────────────── */
358	.panel {
359	    background: rgba(10, 13, 26, 0.7);
360	    border: 1px solid rgba(255, 255, 255, 0.07);
361	    border-radius: 3px;
362	    padding: 20px 22px;
363	    backdrop-filter: blur(12px);
364	    transition: border-color var(--ease), box-shadow var(--ease), transform var(--ease);
365	    margin-bottom: 16px;
366	}
367	.panel:hover {
368	    border-color: var(--cyan-glow);
369	    box-shadow: 0 0 20px hsla(180, 70%, 50%, 0.05);
370	    transform: translateY(-1px);
371	}
372	
373	/* ─── NEURAL INTERFACE UTILITIES ─────────────────────────────────── */
374	.neural-glass {
375	    background: var(--bg-glass);
376	    backdrop-filter: blur(24px) saturate(180%);
377	    border: 1px solid hsla(0, 0%, 100%, 0.08);
378	    border-radius: var(--grid-unit);
379	    transition: border-color var(--transition-master), background-color var(--transition-master), box-shadow var(--transition-master), transform var(--transition-master);
380	}
381	.neural-glass:hover {
382	    border-color: hsla(180, 70%, 50%, 0.3);
383	    background: hsla(220, 15%, 15%, 0.6);
384	}
385	
386	.glow-text {
387	    text-shadow: 0 0 10px var(--cyan-glow);
388	}
389	
390	.critical-pulse {
391	    animation: critical-pulse 2s infinite;
392	}
393	@keyframes critical-pulse {
394	    0% { color: var(--red-fusion); text-shadow: 0 0 0px var(--red-fusion); }
395	    50% { color: hsl(0, 100%, 70%); text-shadow: 0 0 15px var(--red-fusion); }
396	    100% { color: var(--red-fusion); text-shadow: 0 0 0px var(--red-fusion); }
397	}
398	
399	.panel-header {
400	    display: flex;
401	    justify-content: space-between;
402	    align-items: center;
403	    margin-bottom: 4px;
404	}
405	.panel-header h3 {
406	    font-family: var(--font-mono);
407	    font-size: 0.72rem;
408	    letter-spacing: 0.2em;
409	    color: var(--silver-albedo);
410	    opacity: 0.7;
411	}
412	
413	/* ─── TELEMETRY BARS ──────────────────────────────────────────────── */
414	.telemetry-item {
415	    display: flex;
416	    flex-direction: column;
417	    gap: 5px;
418	}
419	.telemetry-label {
420	    font-family: var(--font-mono);
421	    font-size: 0.55rem;
422	    letter-spacing: 0.12em;
423	    opacity: 0.4;
424	}
425	.telemetry-bar-bg {
426	    height: 2px;
427	    background: rgba(255, 255, 255, 0.08);
428	    border-radius: 1px;
429	    overflow: hidden;
430	}
431	.telemetry-bar-fill {
432	    height: 100%;
433	    background: var(--cyan-glow);
434	    border-radius: 1px;
435	    transition: width 1s ease;
436	    box-shadow: 0 0 6px var(--cyan-glow);
437	}
438	
439	/* ─── VAULT / PHYSIS CARDS ────────────────────────────────────────── */
440	.file-node {
441	    background: rgba(10, 13, 26, 0.7);
442	    border: 1px solid rgba(255, 255, 255, 0.07);
443	    border-radius: 3px;
444	    padding: 18px 14px;
445	    cursor: pointer;
446	    text-align: center;
447	    transition: border-color var(--ease), background-color var(--ease), box-shadow var(--ease), transform var(--ease);
448	}
449	.file-node:hover {
450	    border-color: var(--cyan-glow);
451	    background: rgba(0, 242, 255, 0.05);
452	    transform: translateY(-2px);
453	}
454	.vault-icon {
455	    width: 28px; height: 28px;
456	    fill: var(--cyan-glow);
457	    margin: 0 auto;
458	    display: block;
459	}
460	.vault-name {
461	    font-size: 0.72rem;
462	    margin-top: 8px;
463	    word-break: break-all;
464	    line-height: 1.3;
465	}
466	.vault-meta {
467	    font-family: var(--font-mono);
468	    font-size: 0.55rem;
469	    opacity: 0.3;
470	    margin-top: 4px;
471	    letter-spacing: 0.1em;
472	}
473	
474	/* ─── BREADCRUMB ──────────────────────────────────────────────────── */
475	.breadcrumb-bar {
476	    font-family: var(--font-mono);
477	    font-size: 0.68rem;
478	    color: var(--cyan-glow);
479	    margin-bottom: 20px;
480	    opacity: 0.7;
481	}
482	.breadcrumb-item {
483	    cursor: pointer;
484	    transition: opacity var(--ease);
485	}
486	.breadcrumb-item:hover { opacity: 1; text-decoration: underline; }
487	
488	/* ─── KNOWLEDGE CARDS ─────────────────────────────────────────────── */
489	.knowledge-card {
490	    cursor: pointer;
491	    transition: border-color var(--ease);
492	}
493	.knowledge-card:hover {
494	    border-color: var(--cyan-glow) !important;
495	}
496	
497	/* ─── UTILITIES ───────────────────────────────────────────────────── */
498	.text-gold  { color: var(--gold-solar); }
499	.text-cyan  { color: var(--cyan-glow); }
500	.text-mono  { font-family: var(--font-mono); }
501	.text-mono  { font-variant-numeric: tabular-nums; }
502	
503	/* ── SACRED_GEOMETRY // HEARTBEAT ── */
504	.metatrons-cube {
505	    position: fixed;
506	    top: 50%;
507	    left: 50%;
508	    width: 800px;
509	    height: 800px;
510	    transform: translate(-50%, -50%);
511	    opacity: 0.05;
512	    pointer-events: none;
513	    z-index: -1;
514	    background-image: url('data:image/svg+xml;base64,');
515	    background-size: contain;
516	    animation: rotate-heartbeat 60s linear infinite;
517	}
518	
519	@keyframes rotate-heartbeat {
520	    from { transform: translate(-50%, -50%) rotate(0deg) scale(1); }
521	    50% { transform: translate(-50%, -50%) rotate(180deg) scale(1.1); }
522	    to { transform: translate(-50%, -50%) rotate(360deg) scale(1); }
523	}
524	
525	/* ── RICH_GLASSMORPISM ── */
526	.neural-glass {
527	    background: rgba(10, 15, 25, 0.7) !important;
528	    backdrop-filter: blur(25px) saturate(180%) !important;
529	    -webkit-backdrop-filter: blur(25px) saturate(180%) !important;
530	    border: 1px solid rgba(255, 255, 255, 0.1) !important;
531	    box-shadow: 0 12px 40px rgba(0, 0, 0, 0.5), 
532	                inset 0 0 20px rgba(0, 242, 255, 0.03) !important;
533	}
534	
535	.neural-glass:hover {
536	    border: 1px solid rgba(0, 242, 255, 0.3) !important;
537	    box-shadow: 0 12px 50px rgba(0, 242, 255, 0.1) !important;
538	}
539	
540	/* ── SCANLINE_ALIVE ── */
541	.scanline {
542	    width: 100%;
543	    height: 100px;
544	    z-index: 99;
545	    background: linear-gradient(0deg, rgba(0, 242, 255, 0) 0%, rgba(0, 242, 255, 0.05) 50%, rgba(0, 242, 255, 0) 100%);
546	    opacity: 0.1;
547	    position: absolute;
548	    bottom: 100%;
549	    animation: scanline 8s linear infinite;
550	    pointer-events: none;
551	}
552	
553	@keyframes scanline {
554	    0% { bottom: 100%; }
555	    100% { bottom: -100px; }
556	}
557	
558	/* ── GLOW_TEXT_DYNAMIC ── */
559	.glow-text {
560	    text-shadow: 0 0 10px rgba(0, 242, 255, 0.5), 0 0 20px rgba(0, 242, 255, 0.2);
561	    animation: text-flicker 10s infinite;
562	}
563	
564	@keyframes text-flicker {
565	    0%, 100% { opacity: 1; }
566	    98% { opacity: 1; }
567	    99% { opacity: 0.8; }
568	}
569	
570	/* ─── ANIMATIONS ──────────────────────────────────────────────────── */
571	@keyframes pulse {
572	    0% { transform: scale(1); opacity: 1; }
573	    50% { transform: scale(1.1); opacity: 0.7; }
574	    100% { transform: scale(1); opacity: 1; }
575	}
576	
577	@keyframes slideInRight {
578	    from { transform: translateX(100%); opacity: 0; }
579	    to   { transform: translateX(0); opacity: 1; }
580	}
581	
582	/* ─── TACTICAL HUD & MILITARY AESTHETICS ──────────────────────────── */
583	.tactical-hud {
584	    position: relative;
585	    overflow: hidden;
586	}
587	
588	.tactical-hud::before {
589	    content: "";
590	    position: absolute;
591	    top: 0; left: 0; width: 100%; height: 100%;
592	    background: radial-gradient(circle at 50% 50%, rgba(118,185,0,0.05) 0%, transparent 80%);
593	    pointer-events: none;
594	}
595	
596	.pulse-ring {
597	    box-shadow: 0 0 10px var(--gold-solar);
598	    animation: pulse 2s infinite;
599	}
600	
601	.scanline-mini {
602	    position: absolute;
603	    top: 0; left: 0; width: 100%; height: 2px;
604	    background: rgba(0,242,255,0.1);
605	    box-shadow: 0 0 5px var(--cyan-glow);
606	    animation: scanline 4s linear infinite;
607	    pointer-events: none;
608	    z-index: 10;
609	}
610	
611	@keyframes scanline {
612	    from { transform: translateY(-100%); }
613	    to { transform: translateY(500px); }
614	}
615	
616	.hud-stat {
617	    background: rgba(255,255,255,0.03);
618	    border: 1px solid rgba(255,255,255,0.05);
619	    padding: 10px;
620	    text-align: center;
621	}
622	
623	.telemetry-row {
624	    padding: 8px 0;
625	    border-top: 1px solid rgba(255,255,255,0.02);
626	}
627	
628	@keyframes rotate {
629	    from { transform: rotate(0deg); }
630	    to { transform: rotate(360deg); }
631	}
632	
633	/* ─── CONTEXT PANEL ────────────────────────────────────────────── */
634	#context-panel {
