657	    padding: 12px 18px;
658	    background: rgba(10, 13, 26, 0.95);
659	    border: 1px solid rgba(0, 242, 255, 0.3);
660	    box-shadow: 0 10px 30px rgba(0,0,0,0.5), 0 0 15px rgba(0,242,255,0.1);
