672	#hover-tooltip.active {
673	    opacity: 1;
674	    transform: translateY(0);
675	}
676	
677	/* ─── AGENT ICONS (SACRED GEOMETRY) ──────────────────────────────── */
678	.agent-icon {
679	    width: 60px;
680	    height: 60px;
681	    background-image: url('/assets/agent_icons.png');
682	    background-size: 200% 200%;
683	    border: 1px solid rgba(0, 242, 255, 0.2);
684	    border-radius: 4px;
685	    box-shadow: 0 0 15px rgba(0, 242, 255, 0.1);
686	}
687	
688	.agent-icon.type-alpha { background-position: 0% 0%; }
689	.agent-icon.type-beta  { background-position: 100% 0%; }
690	.agent-icon.type-gamma { background-position: 0% 100%; }
691	.agent-icon.type-delta { background-position: 100% 100%; }
692	
693	.gradient-text {
694	    background: linear-gradient(90deg, var(--gold-solar), var(--silver-albedo));
