701	@keyframes benchmark-pulse {
702	    0% { filter: brightness(1) drop-shadow(0 0 5px var(--cyan-glow)44); }
703	    50% { filter: brightness(1.3) drop-shadow(0 0 15px var(--cyan-glow)88); }
704	    100% { filter: brightness(1) drop-shadow(0 0 5px var(--cyan-glow)44); }
705	}
706	
707	.benchmark-bar-fill {
708	    animation: benchmark-pulse 3s ease-in-out infinite;
709	}
710	
711	.card-hover-effect {
712	    transition: transform 0.4s var(--ease-neural), box-shadow 0.4s var(--ease-neural), border-color 0.4s var(--ease-neural);
713	}
714	
715	.card-hover-effect:hover {
716	    transform: translateY(-5px) scale(1.02);
717	    box-shadow: 0 20px 40px rgba(0,0,0,0.4), 0 0 20px rgba(0,242,255,0.1);
718	}
719	
720	/* ─── BRIDGE_v3_EXTENSIONS ────────────────────────────────────────── */
721	.deliberation-box {
722	    border-radius: 4px;
