/* ═══════════════════════════════════════════════════════════════════
   VSC LAYOUT SYSTEM — NUDIMMUD x VSCode
   Dark operator shell re-skinned to VSCode spatial grammar:
   activity-bar | sidebar | editor (title + tabs + breadcrumb + content)
   + status-bar spanning full width at bottom.
   ═══════════════════════════════════════════════════════════════════ */

:root {
    --vsc-activity-w:    48px;
    --vsc-status-h:      22px;
    --vsc-tab-h:         35px;
    --vsc-breadcrumb-h:  22px;
    --vsc-sidebar-bg:    rgba(12, 12, 12, 0.97);
    --vsc-activity-bg:   rgba(8,  8,  8,  0.99);
    --vsc-editor-bg:     rgba(16, 16, 16, 0.88);
    --vsc-titlebar-bg:   rgba(6,  6,  6,  0.97);
    --vsc-tab-bg:        rgba(4,  4,  4,  0.96);
    --vsc-status-bg:     rgba(0, 100, 160, 0.92);
    --vsc-border:        rgba(255, 255, 255, 0.07);
    --vsc-border-active: rgba(159, 232, 115, 0.22);
}

/* ─── SHELL GRID OVERRIDE ─────────────────────────────────────────── */
.app-shell {
    grid-template-columns: var(--vsc-activity-w) var(--sidebar-w) 1fr;
    grid-template-rows: 1fr var(--vsc-status-h);
    /* remove the old 3-row header/main/footer split */
}

/* ─── ACTIVITY BAR (col 1) ────────────────────────────────────────── */
.vsc-activity-bar {
    grid-column: 1;
    grid-row: 1;
    display: flex;
    flex-direction: column;
    align-items: center;
    background: var(--vsc-activity-bg);
    border-right: 1px solid var(--vsc-border);
    pointer-events: auto;
    z-index: 20;
    user-select: none;
}

.vsc-activity-logo {
    width: 100%;
    height: 40px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-bottom: 1px solid var(--vsc-border);
    flex-shrink: 0;
    padding: 4px 0;
}

.vsc-activity-actions {
    flex: 1;
    display: flex;
    flex-direction: column;
    align-items: center;
    padding: 4px 0;
    gap: 0;
    width: 100%;
}

.vsc-activity-btn {
    width: var(--vsc-activity-w);
    height: 48px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: transparent;
    border: none;
    border-left: 2px solid transparent;
    cursor: pointer;
    color: var(--text-dim);
    transition: color 140ms ease, border-color 140ms ease, background 140ms ease;
    flex-shrink: 0;
}

.vsc-activity-btn:hover {
    color: var(--silver-albedo);
    background: rgba(255, 255, 255, 0.05);
}

.vsc-activity-btn.active,
.vsc-activity-btn[aria-pressed="true"] {
    color: var(--silver-albedo);
    border-left-color: var(--cyan-glow);
    background: rgba(255, 255, 255, 0.04);
}

.vsc-activity-btn:focus-visible {
    outline: 1px solid var(--cyan-glow);
    outline-offset: -2px;
}

.vsc-activity-footer {
    padding: 12px 0;
    display: flex;
    flex-direction: column;
    align-items: center;
    border-top: 1px solid var(--vsc-border);
    width: 100%;
}

/* ─── SIDEBAR / MODULE EXPLORER (col 2) ──────────────────────────── */
nav#sidebar-nav {
    grid-column: 2;
    grid-row: 1;
    display: flex;
    flex-direction: column;
    gap: 0;
    align-items: stretch;
    background: var(--vsc-sidebar-bg);
    border-right: 1px solid var(--vsc-border);
    overflow-y: auto;
    overflow-x: hidden;
    padding: 0;
    white-space: nowrap;
    backdrop-filter: none;
    flex-wrap: nowrap;
    width: auto;
    min-width: 0;
    scrollbar-width: thin;
    scrollbar-color: rgba(255,255,255,0.08) transparent;
}

.vsc-sidebar-title {
    font-family: var(--font-mono);
    font-size: 0.52rem;
    letter-spacing: 0.22em;
    color: rgba(255, 255, 255, 0.35);
    padding: 16px 16px 6px;
    text-transform: uppercase;
    user-select: none;
    flex-shrink: 0;
}

.vsc-sidebar-divider {
    height: 1px;
    background: var(--vsc-border);
    margin: 8px 0;
    flex-shrink: 0;
}

.vsc-sidebar-footer {
    margin-top: auto;
    padding: 12px 16px;
    border-top: 1px solid var(--vsc-border);
    flex-shrink: 0;
}

.vsc-sidebar-footer-item {
    display: flex;
    flex-direction: column;
    gap: 2px;
}

/* Override nav nodes from pills to vertical list items */
.nav-node {
    height: 32px;
    min-height: 32px;
    padding: 0 12px 0 18px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
    cursor: pointer;
    border-radius: 0;
    border-left: 2px solid transparent;
    border-bottom: none;
    border-right: none;
    border-top: none;
    background: transparent;
    opacity: 1;
    color: var(--text-dim);
    transition: background 120ms ease, color 120ms ease, border-color 120ms ease;
    font-family: var(--font-mono);
    font-size: 0.70rem;
    letter-spacing: 0.05em;
    flex: 0 0 auto;
    white-space: nowrap;
    box-shadow: none;
}

.nav-node:hover {
    background: rgba(255, 255, 255, 0.05);
    color: var(--silver-albedo);
    opacity: 1;
    transform: none;
}

.nav-node.active {
    color: var(--silver-albedo);
    background: rgba(255, 255, 255, 0.07);
    border-left-color: var(--cyan-glow);
    border-bottom: none;
    border-bottom-color: transparent;
    box-shadow: none;
    opacity: 1;
}

.nav-node:focus-visible {
    outline: 1px solid var(--cyan-glow);
    outline-offset: -2px;
}

.nav-label {
    flex: 1;
}

.nav-badge {
    font-size: 0.7rem;
    flex-shrink: 0;
}

/* ─── EDITOR AREA (col 3) ─────────────────────────────────────────── */
.vsc-editor-area {
    grid-column: 3;
    grid-row: 1;
    display: flex;
    flex-direction: column;
    overflow: hidden;
    position: relative;
    background: var(--vsc-editor-bg);
    pointer-events: auto;
}

/* ─── TITLE BAR (command rail) ────────────────────────────────────── */
header.vsc-title-bar {
    /* detach from grid — it's a flex child of .vsc-editor-area */
    grid-column: unset;
    grid-row: unset;
    flex-shrink: 0;
    min-height: unset;
    height: 40px;
    padding: 0 12px;
    display: flex;
    align-items: center;
    gap: 10px;
    background: var(--vsc-titlebar-bg);
    border-bottom: 1px solid var(--vsc-border);
    box-shadow: none;
    z-index: 10;
}

header.vsc-title-bar .cortex-command-shell {
    flex: 1;
    max-width: none;
    height: 26px;
    padding: 0 10px;
    border-radius: 2px;
    background: rgba(255, 255, 255, 0.06);
    border: 1px solid rgba(255, 255, 255, 0.10);
    box-shadow: none;
    display: flex;
    align-items: center;
    gap: 8px;
}

/* hide the helper hint in compact title bar */
header.vsc-title-bar .command-helper { display: none; }

header.vsc-title-bar .command-row {
    display: flex;
    align-items: center;
    gap: 8px;
    flex: 1;
    min-width: 0;
    flex-wrap: nowrap;
}

header.vsc-title-bar .command-prefix {
    font-size: 0.62rem;
    opacity: 0.5;
}

header.vsc-title-bar #global-command-input {
    font-size: 0.72rem;
}

header.vsc-title-bar .system-status {
    gap: 6px;
    flex-shrink: 0;
}

header.vsc-title-bar .status-pill {
    min-width: unset;
    padding: 4px 8px;
    border-radius: 2px;
}

/* ─── TAB BAR ─────────────────────────────────────────────────────── */
.vsc-tab-bar {
    flex-shrink: 0;
    height: var(--vsc-tab-h);
    display: flex;
    align-items: flex-end;
    background: var(--vsc-tab-bg);
    border-bottom: 1px solid var(--vsc-border);
    overflow-x: auto;
    overflow-y: hidden;
    scrollbar-width: none;
    pointer-events: auto;
}

.vsc-tab-bar::-webkit-scrollbar { display: none; }

.vsc-tab {
    height: 100%;
    padding: 0 16px;
    display: flex;
    align-items: center;
    font-family: var(--font-mono);
    font-size: 0.66rem;
    letter-spacing: 0.07em;
    color: var(--text-dim);
    background: transparent;
    border-right: 1px solid var(--vsc-border);
    border-top: 2px solid transparent;
    cursor: pointer;
    white-space: nowrap;
    transition: color 120ms ease, background 120ms ease, border-color 120ms ease;
    user-select: none;
    flex-shrink: 0;
}

.vsc-tab:hover {
    background: rgba(255, 255, 255, 0.04);
    color: var(--silver-albedo);
}

.vsc-tab.active {
    background: rgba(255, 255, 255, 0.06);
    color: var(--silver-albedo);
    border-top-color: var(--cyan-glow);
}

/* ─── BREADCRUMB ──────────────────────────────────────────────────── */
.vsc-breadcrumb {
    flex-shrink: 0;
    height: var(--vsc-breadcrumb-h);
    display: flex;
    align-items: center;
    padding: 0 14px;
    gap: 4px;
    font-family: var(--font-mono);
    font-size: 0.60rem;
    color: var(--text-dim);
    background: rgba(10, 10, 10, 0.5);
    border-bottom: 1px solid var(--vsc-border);
    pointer-events: auto;
}

.vsc-breadcrumb-sep {
    opacity: 0.35;
    font-size: 0.7rem;
}

.vsc-breadcrumb-item {
    cursor: default;
    transition: color 120ms ease;
}

.vsc-breadcrumb-item:last-child {
    color: var(--silver-albedo);
}

.vsc-breadcrumb-item:not(:last-child):hover {
    color: var(--cyan-glow);
    cursor: pointer;
}

/* ─── EDITOR CONTENT ──────────────────────────────────────────────── */
#module-content.vsc-editor-content {
    flex: 1;
    overflow-y: auto;
    overflow-x: hidden;
    padding: 28px 32px;
    grid-column: unset;
    grid-row: unset;
    scrollbar-width: thin;
    scrollbar-color: rgba(255, 255, 255, 0.09) transparent;
}

/* context panel: fixed overlay within editor, slides in from right */
#context-panel {
    position: fixed;
    top: 0;
    right: 0;
    bottom: var(--vsc-status-h);
    width: var(--panel-w);
    grid-column: unset;
    grid-row: unset;
    background:
        linear-gradient(180deg, rgba(6, 6, 6, 0.98), rgba(12, 12, 12, 0.96)),
        radial-gradient(circle at top, rgba(118, 185, 0, 0.08), transparent 34%);
    border-left: 1px solid rgba(118, 185, 0, 0.12);
    box-shadow: -20px 0 50px rgba(0, 0, 0, 0.5);
    overflow-y: auto;
    padding: 32px 28px;
    transform: translateX(100%);
    transition: transform 0.35s cubic-bezier(0.19, 1, 0.22, 1);
    pointer-events: auto;
    z-index: 50;
}

#context-panel.active {
    transform: translateX(0);
}

/* ─── STATUS BAR (row 2, all cols) ───────────────────────────────── */
footer.vsc-status-bar {
    grid-column: 1 / -1;
    grid-row: 2;
    height: var(--vsc-status-h);
    min-height: var(--vsc-status-h);
    max-height: var(--vsc-status-h);
    padding: 0;
