.vsc-status-right {
    display: flex;
    align-items: center;
    gap: 0;
    flex-shrink: 0;
}

.vsc-status-right { margin-left: auto; }

.vsc-status-item {
    padding: 0 8px;
    height: var(--vsc-status-h);
    display: flex;
    align-items: center;
    gap: 3px;
    white-space: nowrap;
    cursor: default;
    transition: background 120ms ease;
    color: rgba(255, 255, 255, 0.88);
}

.vsc-status-item:hover {
    background: rgba(255, 255, 255, 0.12);
}

.vsc-status-bar-chart {
    gap: 4px;
}

/* ─── RESPONSIVE: COLLAPSE TO SINGLE COLUMN ──────────────────────── */
@media (max-width: 900px) {
